import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,_ as u,b as d,k as f,l as p,n as m,o as h,t as g}from"./shared-BLp3PbbW.js";import{t as _}from"./git-branch-D70e6IXn.js";import{t as v}from"./save-Dm_X5Mwf.js";var y=e();function b({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:`HTTP PATCH`,title:`PATCH и сохранённый ответ`,intro:`Проведём частичное изменение через HTTP и проследим его до сохранённой задачи.`,tags:[{icon:(0,y.jsx)(_,{size:15}),label:`Маршрут FastAPI`},{icon:(0,y.jsx)(v,{size:15}),label:`Проверка состояния`}],variant:`project`}),(0,y.jsxs)(s,{number:`00`,title:`От готового сервиса к HTTP-маршруту`,children:[(0,y.jsx)(o,{children:`Сервис и входную схему подготовили отдельно. Теперь соединим их одним HTTP-маршрутом. PATCH изменит выбранные поля через готовый Planner и вернёт TaskRead. В следующем занятии добавим DELETE.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`Готовы patch_task и TaskPatch. HTTP-маршрута PATCH пока нет.`},{title:`Новый вопрос`,description:`Как соединить готовую схему и сервис одним HTTP-маршрутом?`},{title:`Результат`,description:`Добавим PATCH, вернём TaskRead и проверим сохранение новым чтением.`}]}),(0,y.jsx)(`p`,{children:`Мы не создаём заново схему или операцию сервиса. Добавляем HTTP-вход, который связывает адрес и проверенное тело с готовым Planner, а затем проверяем публичный ответ и сохранённое состояние.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Частичное изменение начинается с формы запроса`,children:[(0,y.jsx)(`p`,{children:`При PUT клиент отправляет всю изменяемую форму, а при PATCH только выбранные поля. Например, чтобы открыть завершённую задачу, достаточно передать is_done=false; title и priority останутся прежними. PATCH здесь подключает уже готовую операцию сервиса и не создаёт новую задачу.`}),(0,y.jsxs)(`p`,{children:[`Разделим запрос на адрес и тело. Путь `,(0,y.jsx)(`code`,{children:`/tasks/{task_id}`}),` содержит ID выбранной задачи, а JSON-body (тело запроса) несёт поля для изменения. Это похоже на конверт: адрес помогает найти получателя, а вложенный лист сообщает, что нужно сделать. Но аналогия ограничена: в HTTP адрес и тело разбирает FastAPI по контракту, а не человек.`]}),(0,y.jsx)(t,{rows:[[`path: /tasks/7`,`выбирает задачу с ID 7`],[`body: {"title":"Купить молоко"}`,`передаёт новое название`],[`положительный ID`,`формат верен, существование ещё не подтверждено`]]}),(0,y.jsx)(`p`,{children:`Фигурные скобки в шаблоне пути отмечают место для значения: запрос к /tasks/7 передаст функции число 7 как task_id. Этот номер выбирает запись, но не доказывает, что запись существует. FastAPI проверяет, что ID является положительным целым; готовый сервис проверяет наличие самой задачи.`}),(0,y.jsx)(`p`,{children:"Маршрут (route) является правилом, связывающее HTTP-метод и путь с функцией приложения. Эту функцию часто называют обработчиком (handler): она связывает проверенный вход с готовым сервисом. `TaskPatch` уже задаёт разрешённые поля `title`, `priority`, `is_done`; FastAPI создаёт из JSON проверенный объект до вызова handler, поэтому тело не нужно разбирать вручную."}),(0,y.jsx)(`p`,{children:"ID не входит в `TaskPatch`: он приходит из пути. `tags` тоже не входит в схему изменений, потому что остаётся частью полной записи, которой управляет Planner. Такое разделение похоже на форму заказа с отдельным номером записи и разрешёнными полями правки; аналогия не означает, что клиент вправе менять любые остальные данные."}),(0,y.jsx)(d,{question:`Запрос PATCH /tasks/7 содержит {"title":"Купить молоко"}. Что выбирает path, а что передаёт body?`,options:[`Path выбирает ID 7, body передаёт новое название`,`Path задаёт title, body выбирает ID`,`Обе части выбирают запись`],correctIndex:0,explanation:`Число в path выбирает задачу; JSON-body содержит только изменение. Положительный ID ещё не подтверждает, что запись существует.`}),(0,y.jsxs)(`p`,{children:["Например, в `PATCH /settings/12` путь выбирает настройку 12, а тело",(0,y.jsx)(`code`,{children:` {"email_enabled": false}`}),` просит выключить уведомления. Клиент не открывает файл настроек и не сохраняет его сам: маршрут передаёт проверенное изменение сервису. Число 12 с правильным форматом всё ещё может не соответствовать существующей настройке.`]})]}),(0,y.jsxs)(s,{number:`02`,title:`Сохраняем разницу между пропуском и False`,children:[(0,y.jsx)(`p`,{children:"У поля есть значение и отдельный признак: прислал ли его клиент. Метод `model_dump()` превращает проверенную модель в словарь. С `exclude_unset=True` в словарь не попадут неприсланные поля; `exclude_none=True` уберёт поля, которым клиент явно передал `null`. Здесь используем оба флага, чтобы сервис получил только эффективные изменения."}),(0,y.jsx)(`p`,{children:"`False` не равен пропуску: это команда снять отметку выполнения. Проверка `if value` ошибочна, потому что сочтёт `False` отсутствием и потеряет изменение. Поэтому различаем факт передачи поля и его значение. Правило относится к этому контракту `TaskPatch`, а не автоматически ко всем схемам."}),(0,y.jsx)(t,{rows:[[`{"is_done": false}`,`changes содержит is_done: false`],[`{"title": null}`,`changes пустой`],[`{}`,`changes пустой`],[`нет body или весь JSON null`,`FastAPI возвращает 422`]]}),(0,y.jsxs)(`p`,{children:[`Пустой объект `,(0,y.jsx)(`code`,{children:`{}`})," и поле title со значением null дают пустой словарь. Для существующей задачи это no-op (операция без изменения): запись остаётся прежней. Само тело при этом обязательно. Отсутствующее тело и весь JSON `null` не заменяются на `","` и дают 422."]}),(0,y.jsxs)(`p`,{children:["Проследим независимый пример на настройках. Пусть в записи `email_enabled` равно `True`, а проверенная схема вернула ",(0,y.jsx)(`code`,{children:`{"email_enabled": false}`}),". После преобразования словарь содержит ключ `email_enabled` со значением `False`; сервис выключит настройку, сохранив остальные ключи. Если поле пропущено или равно `null`, словарь пуст и эта настройка не меняется."]}),(0,y.jsx)(u,{code:`settings = {"email_enabled": True, "weekly_digest": True}
changes = {"email_enabled": False}
settings.update(changes)
print(settings)`,output:`{'email_enabled': False, 'weekly_digest': True}`,hint:`Словарь содержит только переданное изменение. False является значением, а не признаком пропуска ключа.`}),(0,y.jsx)(`p`,{children:"Этот пример показывает преобразование и значение `False`, но не выполняет HTTP-запрос и не сохраняет файл. В нашем маршруте FastAPI уже создал `TaskPatch`; мы передадим полученный словарь готовому методу сервиса."})]}),(0,y.jsxs)(s,{number:`03`,title:`Маршрут соединяет проверку, сервис и ответ`,children:[(0,y.jsx)(`p`,{children:"API принимает HTTP-запрос и формирует HTTP-ответ. `PlannerService` отвечает за изменение задачи и сохранение через общее хранилище. Поэтому handler не ищет запись в JSON, не собирает Task вручную и не вызывает `save`."}),(0,y.jsx)(g,{caption:`Путь PATCH от HTTP-запроса до публичного ответа`,orientation:`vertical`,children:(0,y.jsxs)(h,{label:`Обработка PATCH запроса`,orientation:`vertical`,children:[(0,y.jsx)(p,{title:`HTTP-запрос`,children:(0,y.jsx)(`p`,{children:`task_id и JSON тела`})}),(0,y.jsx)(m,{label:`FastAPI проверяет путь и body`,direction:`forward`}),(0,y.jsx)(p,{title:`Словарь changes`,children:(0,y.jsx)(`p`,{children:`только присланные значения`})}),(0,y.jsx)(m,{label:`PlannerService.patch_task`,direction:`forward`}),(0,y.jsx)(p,{title:`Сохранённая Task`,shape:`database`,children:(0,y.jsx)(`p`,{children:`полная доменная запись`})}),(0,y.jsx)(m,{label:`TaskRead формирует публичный ответ`,direction:`forward`,lineStyle:`dashed`}),(0,y.jsx)(p,{title:`HTTP-ответ`,children:(0,y.jsx)(`p`,{children:`id, title, priority, is_done`})})]})}),(0,y.jsx)(`p`,{children:"На входе FastAPI проверяет положительный `task_id` и обязательное тело `TaskPatch`. Параметр `Request` представляет текущий запрос; через `request.app.state.planner` он даёт handler тот же Planner, который используют другие маршруты. Затем handler получает `changes` с двумя флагами и вызывает готовый `patch_task`."}),(0,y.jsxs)(`p`,{children:["Запись `**changes` передаёт ключи словаря как именованные аргументы: словарь",(0,y.jsx)(`code`,{children:`{"is_done": false}`})," становится вызовом `patch_task(task_id, is_done=False)`. Пустой словарь не содержит полей для изменения, но вызов всё равно передаёт ID сервису для поиска. Сервис находит задачу, применяет разрешённые значения и сохраняет результат."]}),(0,y.jsx)(r,{tone:`info`,children:`Маршрут связывает вход с сервисом; сервис владеет изменением и сохранением.`}),(0,y.jsx)(`p`,{children:"Вызов `_call_with_task_not_found_as_404` переводит только `TaskNotFoundError` в 404. Ошибка `StorageError` не становится ошибкой «не найдено». Затем `_task_read_data` подготавливает данные, а `response_model=TaskRead` ограничивает ответ четырьмя публичными полями."}),(0,y.jsx)(`p`,{children:"`TaskRead` задаёт публичную проекцию полной записи: клиент видит `id`, `title`, `priority`, `is_done`, но не внутреннее `tags`. Представим окно выдачи: оно показывает поля, предусмотренные для клиента, а не всю внутреннюю карточку. Аналогия описывает только видимость ответа; она не означает, что скрытые поля удалены. Их сохраняет существующий сервис."}),(0,y.jsx)(d,{question:`Какой слой должен непосредственно вызвать PlannerService.patch_task?`,options:[`HTTP-маршрут`,`JSON-файл`,`клиентский интерфейс`],correctIndex:0,explanation:`Маршрут передаёт проверенные изменения сервису. Сервис обновляет задачу и сохраняет её.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Ошибка зависит от того, на каком шаге остановился запрос`,children:[(0,y.jsx)(n,{code:`try:
    task = request.app.state.planner.patch_task(task_id, **changes)
except Exception as error:
    raise HTTPException(status_code=404, detail="Task not found") from error`,question:`Что произойдёт, если patch_task завершится с StorageError?`,options:[`404: широкий except скроет ошибку хранения`,`422: FastAPI отклонит уже проверенное тело`,`200: маршрут вернёт пустой ответ`],correctIndex:0,explanation:`except Exception поймает и TaskNotFoundError, и StorageError. Помощник переводит в 404 только отсутствие задачи.`,fix:`task = _call_with_task_not_found_as_404(
    request.app.state.planner.patch_task, task_id, **changes
)`}),(0,y.jsx)(`p`,{children:"FastAPI проверяет путь и тело до запуска handler. Строка вместо числа, 0 или отрицательное значение не подходит `Path(gt=0)` и даёт 422. Положительный целый ID проходит проверку формата, но записи может не быть: тогда сервис сообщает `TaskNotFoundError`, а helper возвращает 404."}),(0,y.jsx)(`p`,{children:"`TaskPatch` также отклонит пустой `title`; отсутствующее тело и JSON `null` дают 422 до вызова сервиса. Если чтение или запись завершится `StorageError`, это сбой хранилища. Общий `except Exception` ошибочно замаскировал бы его под 404, поэтому helper ловит только `TaskNotFoundError`."}),(0,y.jsx)(t,{rows:[[`200`,`задача найдена, ответ содержит TaskRead`],[`422`,`неверный path или body, сервис не вызван`],[`404`,`ID допустимый, но задача не найдена`],[`StorageError`,`сбой хранилища остаётся отдельной ошибкой`]]}),(0,y.jsx)(`p`,{children:`После отказа сравним запись с исходным снимком. При 422 handler не запускался; при 404 сервис не нашёл задачу. Сбой хранилища отличается от обоих: его причина должна остаться видимой, а не маскироваться статусом отсутствующей записи.`}),(0,y.jsxs)(`p`,{children:[`Для проверки 404 не угадываем ID. Сначала отправляем GET`,` `,(0,y.jsx)(`code`,{children:`/tasks/{candidate_id}`}),`. Если ответ 200, выбираем другой положительный ID. Если ответ 404, этим же ID проверяем PATCH с полем и PATCH с `,(0,y.jsx)(`code`,{children:`{}`}),`. Оба запроса должны вернуть 404, потому что сервис всё равно ищет задачу. Так мы проверяем и пустые изменения, и отсутствие ресурса.`]}),(0,y.jsx)(c,{statement:`Для отсутствующего ID пустой PATCH {} вернёт 200, потому что менять нечего.`,isTrue:!1,explanation:`Сервис получает ID и ищет задачу. Пустой PATCH для существующей задачи ничего не меняет, а для отсутствующей вернёт 404.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Ответ и сохранённая задача показывают разные стороны результата`,children:[(0,y.jsx)(`p`,{children:`TaskPatch принимает title, priority и is_done. Она не принимает id и tags, поэтому эти поля нельзя изменить этим маршрутом. TaskRead задаёт публичный ответ: id, title, priority и is_done. Полная Task также хранит tags, но схема ответа их не показывает. Отсутствие tags в ответе не означает, что они удалены из JSON.`}),(0,y.jsx)(`p`,{children:"Перед запросом запишем состояние выбранной задачи и статистику. `GET /tasks` показывает публичные поля, а `GET /stats` показывает `total`, `open` и `done`. Через привычный CLI проверим полную запись и `tags`; API и CLI должны использовать один настроенный JSON."}),(0,y.jsx)(t,{rows:[[`GET /tasks/{id}`,`актуальные публичные поля задачи`],[`GET /stats`,`счётчики total, open и done`],[`CLI / тот же JSON`,`полная запись, tags и соседняя задача`]]}),(0,y.jsx)(`p`,{children:`Для проверки False нужна завершённая задача. Если такой нет, выберите существующую и отметьте её готовым PUT: задайте is_done=true и сохраните прежние title и priority. PUT требует полную форму, поэтому эти значения нельзя пропускать. Если список пуст, создайте одну задачу готовым POST, возьмите ID из ответа и завершите её готовым PUT. После подготовки снова прочитайте задачу, статистику и CLI. Этот снимок будет исходной точкой.`}),(0,y.jsx)(`p`,{children:`Снимок делаем после подготовки: PUT или POST уже меняет данные. Записываем фактический ID и значения одной соседней записи. После PATCH читаем тот же JSON, к которому подключено приложение, чтобы обнаружить и неверный путь к хранилищу, и случайное изменение соседа.`}),(0,y.jsx)(l,{question:`Какой вариант надёжнее подтверждает, что PATCH сохранил изменение?`,left:{title:`Сверить только ответ PATCH`,code:`PATCH /tasks/{task_id}
# ответ содержит is_done: false`,note:`Проверяет контракт ответа, но не делает отдельного чтения.`},right:{title:`Проверить ответ и перечитать задачу`,code:`PATCH /tasks/{task_id}
GET /tasks/{task_id}
# сверить фактические поля`,note:`Проверяет HTTP-ответ и состояние после завершения запроса.`},preferred:`right`,explanation:`Ответ подтверждает публичную форму. Новый GET или CLI подтверждает сохранённое состояние.`}),(0,y.jsx)(`p`,{children:"После PATCH проверим статус 200 и четыре поля ответа, затем перечитаем ту же задачу через GET и CLI. Сверим новое `is_done`, прежние `title` и `priority`, `tags` и запись-соседа с исходным снимком. Ответ проверяет публичный контракт; новое чтение проверяет сохранённое состояние."}),(0,y.jsx)(`p`,{children:"При ошибочном запросе задача должна остаться в состоянии после успешного PATCH, а соседняя запись должна остаться в исходном состоянии. Если `is_done` изменился с `true` на `false`, `total` прежний, `open` увеличился на 1, `done` уменьшился на 1. Поэтому одного `total` недостаточно: сверим задачу и все три счётчика."})]}),(0,y.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(f,{variant:`connected`,items:[{title:`Исходный снимок готов`,description:`Сверим GET, статистику и CLI до изменений.`},{title:`Маршрут PATCH добавлен`,description:`Передадим TaskPatch прежнему сервису и вернём TaskRead.`},{title:`Границы проверены`,description:`Сравним False, no-op, 422 и 404 на реальном API.`},{title:`Сохранение подтверждено`,description:`Перечитаем ту же задачу через GET и CLI.`}]}),(0,y.jsx)(`p`,{children:`Сначала сохраним исходные поля, tags, статистику и данные соседа. Затем добавим один маршрут PATCH. Проверим is_done=false, пустой объект и null в поле. Эти запросы покажут разницу между изменением и no-op.`}),(0,y.jsx)(`p`,{children:`Отдельно проверим неверный ввод и отсутствующий ID. В конце перечитаем ту же задачу через GET и CLI, затем сравним её с исходным снимком. Так практика проверит и HTTP-ответ, и сохранённые данные. Следующее занятие добавит DELETE, его здесь не реализуем.`})]})]})}export{b as Lesson54_2};